html=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deloitte · Productividad 10x</title><meta name="description" content="Productividad 10x. Fundamentos de IA, inteligencia y velocidad, principios y conceptos clave. Contenido actualizado y gráficos animados."><style>{css}</style></head><body><header id="top"><img src="{LOGO}" alt="Deloitte"><span>Productividad 10x</span><div><button id="index-button">Índice</button><button id="notes-button">Notas</button><button id="sources-button">Fuentes</button><button id="data-button">Datos</button><button id="fullscreen-button" aria-label="Pantalla completa">⛶</button></div></header><div id="viewport"><main id="stage">{slides_html}</main></div><nav id="bottom" aria-label="Navegación de la presentación"><div id="progress"></div><div class="nav-left"><button id="prev" aria-label="Anterior">←</button><input id="slide-number" type="number" min="1" max="{len(slides)}" aria-label="Diapositiva"><span>/ {len(slides)}</span><button id="next" aria-label="Siguiente">→</button></div><span id="chapter"></span><div class="nav-right"><button id="replay">Repetir animación</button><span class="date">14.09.2026</span></div></nav><dialog id="panel"><header><h2 id="panel-title"></h2><button id="panel-close" aria-label="Cerrar">×</button></header><div id="panel-body"></div></dialog><template id="source-template">{source_html}</template><div id="tooltip" role="tooltip"></div><script>const SLIDES={json.dumps([{k:v for k,v in r.items() if k!='body'} for r in slides],ensure_ascii=False)}, DATA={json.dumps(DATA,ensure_ascii=False,allow_nan=False)}, SOURCES={json.dumps(SOURCES,ensure_ascii=False)};</script><script>{js}</script></body></html>'''
